message.content:
I have enough information. Here is the 18-scene illustrated story plan.

{
  "title": "the banner rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party arrives at the ruined gate.",
      "visual_description": "A massive stone gate with broken ironwork, dusk light, old royal banners hang torn from the archway. A map reader studies a brass compass outside the threshold.",
      "characters": ["map_reader", "scout"]
    },
    {
      "scene_number": 2,
      "caption": "Frightened townspeople whisper warnings.",
      "visual_description": "A narrow market street lined with shuttered stalls. A few huddled townspeople point toward a distant tower, their faces shadowed.",
      "characters": ["townsfolk", "scout", "map_reader"]
    },
    {
      "scene_number": 3,
      "caption": "A patrol blocks the main avenue.",
      "visual_description": "Four armored soldiers in dented breastplates stand shoulder to shoulder under a broken arch, torches flickering in cold blue dusk.",
      "characters": ["armored_patrol", "scout", "map_reader"]
    },
    {
      "scene_number": 4,
      "caption": "The team finds a hidden passage.",
      "visual_description": "A crumbling wall behind a collapsed fountain reveals a narrow stairwell, old royal banners draped over the entrance.",
      "characters": ["scout", "map_reader"]
    },
    {
      "scene_number": 5,
      "caption": "A magic door blocks the tunnel.",
      "visual_description": "A door of pale stone with glowing runes, set into a damp stone corridor. A magic helper presses a crystal key against the runes.",
      "characters": ["magic_helper", "scout", "map_reader"]
    },
    {
      "scene_number": 6,
      "caption": "The party enters the cursed tower.",
      "visual_description": "A circular room with a spiraling staircase, cold blue light from high windows, torn banners hanging from the walls.",
      "characters": ["magic_helper", "scout", "map_reader"]
    },
    {
      "scene_number": 7,
      "caption": "Rumors of a dragon echo in the tower.",
      "visual_description": "A large faded mural of a dragon on the tower wall, a single burning torch below it. The team pauses and listens.",
      "characters": ["magic_helper", "scout", "map_reader", "sleepy_official"]
    },
    {
      "scene_number": 8,
      "caption": "The sleepy official wakes from a nap.",
      "visual_description": "A small alcove with a straw bed, a groggy official in a rumpled tunic rubbing their eyes, a ledger stamp on the floor.",
      "characters": ["sleepy_official", "magic_helper", "scout"]
    },
    {
      "scene_number": 9,
      "caption": "The official reveals the captive's location.",
      "visual_description": "The official points to a map on the table, a brass compass beside it, warm lamp light illuminating the room.",
      "characters": ["sleepy_official", "map_reader", "scout", "magic_helper"]
    },
    {
      "scene_number": 10,
      "caption": "The team climbs to the top of the tower.",
      "visual_description": "A spiral staircase with narrow arrow slits, cold moonlight streaming in, the party ascending single file.",
      "characters": ["map_reader", "scout", "magic_helper", "sleepy_official"]
    },
    {
      "scene_number": 11,
      "caption": "A mirror door opens onto the prisoner.",
      "visual_description": "A tall mirror with a silver frame swings open to reveal a small cell, a bound figure sitting on a stone bench.",
      "characters": ["rescued_prisoner", "magic_helper", "scout"]
    },
    {
      "scene_number": 12,
      "caption": "The prisoner is freed with a crystal key.",
      "visual_description": "The magic helper fits the crystal key into the prisoner's manacles, which fall away with a soft glow.",
      "characters": ["rescued_prisoner", "magic_helper", "scout", "map_reader"]
    },
    {
      "scene_number": 13,
      "caption": "Alarms sound through the tower.",
      "visual_description": "A bell rings in the tower, armored footsteps echo from below, the party gathers at the top of the stairs.",
      "characters": ["rescued_prisoner", "map_reader", "scout", "magic_helper", "sleepy_official"]
    },
    {
      "scene_number": 14,
      "caption": "The party races through the mirror hall.",
      "visual_description": "A long hall lined with tall mirrors reflecting the fleeing group, torches flickering, old banners on the walls.",
      "characters": ["rescued_prisoner", "map_reader", "scout", "magic_helper", "sleepy_official"]
    },
    {
      "scene_number": 15,
      "caption": "They reach the old plaza.",
      "visual_description": "A wide stone plaza with a dry fountain, broken statues, and the bridge controls on the far side under a pale sky.",
      "characters": ["rescued_prisoner", "map_reader", "scout", "magic_helper", "sleepy_official"]
    },
    {
      "scene_number": 16,
      "caption": "The bridge lever is pulled.",
      "visual_description": "The scout pulls a heavy iron lever on a stone pedestal, a chains mechanism groaning as the bridge begins to lower.",
      "characters": ["scout", "map_reader", "rescued_prisoner", "magic_helper", "sleepy_official"]
    },
    {
      "scene_number": 17,
      "caption": "The armored patrol reaches the bridge.",
      "visual_description": "The patrol strides onto the bridge from the city side, torches raised, the party already halfway across.",
      "characters": ["armored_patrol", "rescued_prisoner", "map_reader", "scout", "magic_helper", "sleepy_official"]
    },
    {
      "scene_number": 18,
      "caption": "The party escapes as the sun rises.",
      "visual_description": "Warm sunrise over the bridge, the party reaches the far side, the city ruins behind them silhouetted in gold light.",
      "characters": ["rescued_prisoner", "map_reader", "scout", "magic_helper", "sleepy_official"]
    }
  ]
}

